import sys
from collections import deque

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def build_tree(nodes):
    if not nodes:
        return None
    root = Node(int(nodes[0]))
    queue = deque([root])
    idx = 1
    while queue and idx < len(nodes):
        current = queue.popleft()
        if idx < len(nodes) and nodes[idx] != 'null':
            current.left = Node(int(nodes[idx]))
            queue.append(current.left)
        idx += 1
        if idx < len(nodes) and nodes[idx] != 'null' and idx < len(nodes):
            current.right = Node(int(nodes[idx]))
            queue.append(current.right)
        idx += 1
    return root

def printPaths(root, target_sum):
    result = []

    def dfs(node, current_path, current_sum):
        if not node:
            return

        current_path.append(node.data)
        new_sum = current_sum + node.data

        if new_sum == target_sum:
            result.append(list(current_path))

        dfs(node.left, current_path, new_sum)
        dfs(node.right, current_path, new_sum)

        current_path.pop()

    dfs(root, [], 0)
    return result

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    try:
        target_sum = int(input_data[0])
        nodes = input_data[1:]
    except IndexError:
        return

    root = build_tree(nodes)
    paths = printPaths(root, target_sum)

    for path in paths:
        print(" ".join(map(str, path)))

if __name__ == "__main__":
    main()
